def hidden_rule_fn(state):
    # Convert state to a dict of (x,y) -> type
    grid = {}
    for p in state:
        grid[(p['x'], p['y'])] = p['type']

    # If all particles are the same type, nothing moves
    types = set(p['type'] for p in state)
    if len(types) == 1:
        return [dict(p) for p in state]

    # Each particle moves by (+1, +1) on the toroidal 8x8 grid
    result = []
    for p in state:
        new_x = (p['x'] + 1) % 8
        new_y = (p['y'] + 1) % 8
        # If the target position is occupied, stay put
        if (new_x, new_y) in grid:
            result.append(dict(p))
        else:
            result.append({'type': p['type'], 'x': new_x, 'y': new_y})

    return result
